import json

def deep_merge(a, b):
    """
    Recursively merges two JSON-like structures (dicts, lists, scalars).
    - If both are dicts: merge recursively.
    - If both are lists: concatenate and remove duplicates while preserving order.
    - If types differ or are scalars: value from b overrides a.
    """
    if isinstance(a, dict) and isinstance(b, dict):
        merged = a.copy()
        for key, value in b.items():
            if key in merged:
                merged[key] = deep_merge(merged[key], value)
            else:
                merged[key] = value
        return merged
    elif isinstance(a, list) and isinstance(b, list):
        combined = a + b
        result = []
        for item in combined:
            if item not in result:
                result.append(item)
        return result
    else:
        return b

