import * as fs from 'fs';

const logFilePath = '/tmp/…/app.log';

function main() {
  try {
    const data = fs.readFileSync(logFilePath, 'utf8');
    const lines = data.split(/\r?\n/);

    const levelCounts: Record<string, number> = {};
    const errorCountsByComponent: Record<string, number> = {};
    const uniqueErrorMessages: Set<string> = new Set();
    const hourCounts: Record<string, number> = {};

    // Regex to capture: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
    // Group 1: Hour (HH)
    // Group 2: Level
    // Group 3: Component
    // Group 4: Message
    const logRegex = /^\[\d{4}-\d{2}-\d{2} (\d{2}):\d{2}:\d{2}\] (\w+) \((.+)\) - (.*)$/;

    for (const line of lines) {
      const match = line.match(logRegex);
      if (match) {
        const [_, hour, level, component, message] = match;

        // Count occurrences of each level
        levelCounts[level] = (levelCounts[level] || 0) + 1;

        // Count occurrences per hour
        hourCounts[hour] = (hourCounts[hour] || 0) + 1;

        // Track errors
        if (level === 'ERROR') {
          errorCountsByComponent[component] = (errorCountsByComponent[component] || 0) + 1;
          uniqueErrorMessages.add(message);
        }
      }
    }

    console.log("=== Log Analysis ===");
    console.log("");

    console.log("Entries by Level:");
    const sortedLevels = Object.keys(levelCounts).sort();
    sortedLevels.forEach(lvl => {
      console.log(`  ${lvl}: ${levelCounts[lvl]}`);
    });

    console.log("");

    let maxErrors = 0;
    let mostErrorComponent = "None";
    for (const comp in errorCountsByComponent) {
      if (errorCountsByComponent[comp] > maxErrors) {
        maxErrors = errorCountsByComponent[comp];
        mostErrorComponent = comp;
      }
    }
    console.log(`Component with Most Errors: ${mostErrorComponent} (${maxErrors} errors)`);

    console.log("");

    console.log("Unique Error Messages:");
    const sortedMessages = Array.from(uniqueErrorMessages).sort();
    sortedMessages.forEach(msg => {
      console.log(`  - ${msg}`);
    });

    console.log("");

    let maxHourCount = 0;
    let busiestHour = "00";
    for (const hour in hourCounts) {
      if (hourCounts[hour] > maxHourCount) {
        maxHourCount = hourCounts[hour];
        busiestHour = hour;
      }
    }
    console.log(`Busiest Hour: ${busiestHour}:00 (${maxHourCount} entries)`);

  } catch (err) {
    // Fail silently or handle as needed
  }
}

