/**
 * Helper to determine if a value is a plain object.
 */
function isObject(val: any): val is Record<string, any> {
  return val !== null && typeof val === 'object' && !Array.isArray(val);
}

/**
 * Performs deep equality check between two values.
 */
function deepEqual(a: any, b: any): boolean {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (a === null || b === null) return a === b;

  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  if (isObject(a) && isObject(b)) {
    const keysA = Object.keys(a);
    const keysB = Object.keys(b);
    if (keysA.length !== keysB.length) return false;
    for (const key of keysA) {
      if (!Object.prototype.hasOwnProperty.call(b, key) || !deepEqual(a[key], b[key])) {
        return false;
      }
    }
    return true;
  }

  return false;
}

/**
 * Deep merges two objects based on the specified rules:
 * - Both objects: Recursive merge.
 * - Both arrays: Concatenate and remove duplicates (preserve order, A first).
 * - Scalar conflict: B overrides A.
 * - Unique keys: Included as-is.
 */
function deepMerge(a: any, b: any): any {
  if (isObject(a) && isObject(b)) {
    const result: Record<string, any> = { ...a };
    for (const key in b) {
      if (Object.prototype.hasOwnProperty.call(b, key)) {
        if (Object.prototype.hasOwnProperty.call(a, key)) {
          result[key] = deepMerge(a[key], b[key]);
        } else {
          result[key] = b[key];
        }
      }
    }
    return result;
  } else if (Array.isArray(a) && Array.isArray(b)) {
    const combined = [...a, ...b];
    const unique: any[] = [];
    for (const item of combined) {
      if (!unique.some((u) => deepEqual(u, item))) {
        unique.push(item);
      }
    }
    return unique;
  }
  // Scalar conflict or mismatched types: B overrides A
  return b;
}

/**
 * Recursively sorts all object keys alphabetically.
 */
function sortObjectKeys(obj: any): any {
  if (Array.isArray(obj)) {
    return obj.map(sortObjectKeys);
  } else if (isObject(obj)) {
    const sortedKeys = Object.keys(obj).sort();
    const result: Record<string, any> = {};
    for (const key of sortedKeys) {
      result[key] = sortObjectKeys(obj[key]);
    }
    return result;
  }
  return obj;
}

