import * as fs from 'fs';

/**
 * The program reads a CSV file containing employee data and generates a 
 * formatted salary report. It calculates average salaries per department, 
 * identifies the highest-paid employee, lists departments with more 
 * than two employees, and calculates the total budget.
 */
function generateSalaryReport() {
  const filePath = '/tmp/…/employees.csv';

  try {
    // Read the file content synchronously
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split(/\r?\n/);

    if (lines.length < 2) {
      return;
    }

    // Parse CSV lines, skipping the header
    const employees = lines.slice(1)
      .filter(line => line.trim() !== '')
      .map(line => {
        const columns = line.split(',');
        return {
          id: columns[0]?.trim(),
          name: columns[1]?.trim(),
          department: columns[2]?.trim(),
          salary: parseFloat(columns[3]?.trim() || '0'),
          startDate: columns[4]?.trim(),
          rating: columns[5]?.trim()
        };
      });

    const departmentStats: Record<string, { totalSalary: number; count: number }> = {};
    let highestPaid: { name: string; salary: number } = { name: '', salary: -1 };
    let totalBudget = 0;

    // Aggregate data
    employees.forEach(emp => {
      if (!departmentStats[emp.department]) {
        departmentStats[emp.department] = { totalSalary: 0, count: 0 };
      }
      departmentStats[emp.department].totalSalary += emp.salary;
      departmentStats[emp.department].count += 1;

      totalBudget += emp.salary;

      if (emp.salary > highestPaid.salary) {
        highestPaid = { name: emp.name, salary: emp.salary };
      }
    });

    // Output the report
    console.log("=== Salary Report ===\n");

    console.log("Average Salary by Department:");
    const sortedDepartments = Object.keys(departmentStats).sort();
    sortedDepartments.forEach(dept => {
      const stats = departmentStats[dept];
      const average = stats.totalSalary / stats.count;
      // Format average salary with 2 decimal places and commas
      const formattedAvg = average.toLocaleString('en-US', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      });
      console.log(`  ${dept}: $${formattedAvg}`);
    });

    // Highest Paid line with integer formatting and commas
    console.log(`\nHighest Paid: ${highestPaid.name} ($${Math.round(highestPaid.salary).toLocaleString('en-US')})`);

    console.log("\nDepartments with >2 employees:");
    sortedDepartments.forEach(dept => {
      if (departmentStats[dept].count > 2) {
        console.log(`  ${dept} (${departmentStats[dept].count} employees)`);
      }
    });

    // Total Budget line with integer formatting and commas
    console.log(`\nTotal Budget: $${Math.round(totalBudget).toLocaleString('en-US')}`);

  } catch (error) {
    // Silent error handling as per requirements
  }
}

// Execute the program
generateSalaryReport();

import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) {
        String path = "/tmp/…/employees.csv";
        List<Employee> employees = new ArrayList<>();

        try (BufferedReader br = new BufferedReader(new FileReader(path))) {
            String line;
            boolean isFirstLine = true;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",");
                if (parts.length < 4) continue;

                if (isFirstLine) {
                    if (parts[0].trim().equalsIgnoreCase("employee_id")) {
                        isFirstLine = false;
                        continue;
                    }
                    isFirstLine = false;
                }

                try {
                    String name = parts[1].trim();
                    String dept = parts[2].trim();
                    double salary = Double.parseDouble(parts[3].trim());
                    employees.add(new Employee(name, dept, salary));
                } catch (NumberFormatException e) {
                    // Skip lines with invalid salary data
                }
            }
        } catch (IOException e) {
            // File reading error handled silently
        }

        TreeMap<String, Double> deptSalaries = new TreeMap<>();
        TreeMap<String, Integer> deptCounts = new TreeMap<>();
        double maxSalary = -1;
        String maxName = "";
        double totalBudget = 0;

        for (Employee e : employees) {
            deptSalaries.put(e.department, deptSalaries.getOrDefault(e.department, 0.0) + e.salary);
            deptCounts.put(e.department, deptCounts.getOrDefault(e.department, 0) + 1);
            totalBudget += e.salary;
            if (e.salary > maxSalary) {
                maxSalary = e.salary;
                maxName = e.name;
            }
        }

        DecimalFormat avgFormat = new DecimalFormat("$#,##0.00", new DecimalFormatSymbols(Locale.US));
        DecimalFormat intFormat = new DecimalFormat("$#,##0", new DecimalFormatSymbols(Locale.US));

        System.out.println("=== Salary Report ===");
        System.out.println();
        System.out.println("Average Salary by Department:");
        for (String dept : deptSalaries.keySet()) {
            double avg = deptSalaries.get(dept) / deptCounts.get(dept);
            System.out.println("  " + dept + ": " + avgFormat.format(avg));
        }
        System.out.println();
        System.out.println("Highest Paid: " + maxName + " (" + intFormat.format(Math.round(maxSalary)) + ")");
        System.out.println();
        System.out.println("Departments with >2 employees:");
        for (String dept : deptCounts.keySet()) {
            if (deptCounts.get(dept) > 2) {
                System.out.println("  " + dept + " (" + deptCounts.get(dept) + " employees)");
            }
        }
        System.out.println();
        System.out.println("Total Budget: " + intFormat.format(Math.round(totalBudget)));
    }

    static class Employee {
        String name;
        String department;
        double salary;

        Employee(String name, String department, double salary) {
            this.name = name;
            this.department = department;
            this.salary = salary;
        }
    }
}

import Foundation

struct Product: Codable {
    let id: Int
    let name: String
    let price: Double
    let category: String
    let stock: Int
}

let url = URL(string: "http://127.0.0.1:18924/api/products")!
let semaphore = DispatchSemaphore(value: 0)

let task = URLSession.shared.dataTask(with: url) { data, _, _ in
    defer { semaphore.signal() }
    guard let data = data else { return }

    do {
        let products = try JSONDecoder().decode([Product].self, from: data)
        let filtered = products
            .filter { $0.price > 50.00 }
            .sorted { $0.name < $1.name }

        print("=== Filtered Products (price > $50.00) ===")
        print("")

        var total = 0.0
        for product in filtered {
            print("\(product.name): $\(String(format: "%.2f", product.price))")
            total += product.price
        }

        print("")
        print("Count: \(filtered.count)")
        print("Total: $\(String(format: "%.2f", total))")
    } catch {
        // Error handling not specified in output requirements
    }
}

task.resume()
semaphore.wait()

interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  stock: number;
}

async function fetchAndProcessProducts(): Promise<void> {
  try {
    const response = await fetch('http://127.0.0.1:18924/api/products');
    const products: Product[] = await response.json();

    const filtered = products
      .filter((p) => p.price > 50.00)
      .sort((a, b) => a.name.localeCompare(b.name));

    let total = 0;
    console.log("=== Filtered Products (price > $50.00) ===");
    console.log("");

    filtered.forEach((p) => {
      console.log(`${p.name}: $${p.price.toFixed(2)}`);
      total += p.price;
    });

    console.log("");
    console.log(`Count: ${filtered.length}`);
    console.log(`Total: $${total.toFixed(2)}`);
  } catch (error) {
    // Silent catch to ensure no extra output is produced on failure
  }
}

fetchAndProcessProducts();

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String filePath = "/tmp/…/app.log";
        TreeMap<String, Integer> levelCounts = new TreeMap<>();
        Map<String, Integer> componentErrors = new HashMap<>();
        TreeSet<String> uniqueErrorMessages = new TreeSet<>();
        Map<String, Integer> hourCounts = new HashMap<>();

        try (BufferedReader br = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = br.readLine()) != null) {
                if (line.trim().isEmpty()) continue;

                // Expected format: [YYYY-MM-DD HH:MM:SS] LEVEL (component) - message
                int bracketEnd = line.indexOf("] ");
                if (bracketEnd == -1) continue;

                String timestamp = line.substring(1, bracketEnd);
                String rest = line.substring(bracketEnd + 2);

                int firstSpace = rest.indexOf(" ");
                if (firstSpace == -1) continue;
                String level = rest.substring(0, firstSpace);

                int closingBracket = rest.indexOf(") - ");
                if (closingBracket == -1) continue;

                String componentPart = rest.substring(firstSpace + 1, closingBracket);
                String component = componentPart.substring(1, componentPart.length() - 1);
                String message = rest.substring(closingBracket + 4);

                // Update Level Counts
                levelCounts.put(level, levelCounts.getOrDefault(level, 0) + 1);

                // Update Hour Counts
                // Timestamp format is YYYY-MM-DD HH:MM:SS, hour is at index 11 and 12
                if (timestamp.length() >= 13) {
                    String hour = timestamp.substring(11, 13);
                    hourCounts.put(hour, hourCounts.getOrDefault(hour, 0) + 1);
                }

                // Error specific logic
                if ("ERROR".equals(level)) {
                    componentErrors.put(component, componentErrors.getOrDefault(component, 0) + 1);
                    uniqueErrorMessages.add(message);
                }
            }
        } catch (IOException e) {
            // File not found or inaccessible, program will proceed with empty data
        }

        System.out.println("=== Log Analysis ===");
        System.out.println();

        System.out.println("Entries by Level:");
        for (Map.Entry<String, Integer> entry : levelCounts.entrySet()) {
            System.out.println("  " + entry.getKey() + ": " + entry.getValue());
        }
        System.out.println();

        String mostErrorComponent = "None";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                mostErrorComponent = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + mostErrorComponent + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : uniqueErrorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        String busiestHour = "00";
        int maxHourEntries = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > maxHourEntries) {
                maxHourEntries = entry.getValue();
                busiestHour = entry.getKey();
            }
        }
        System.out.println("Busiest Hour: " + busiestHour + ":00 (" + maxHourEntries + " entries)");
    }
}

