        String mostErrorComponent = "None";
        int maxErrors = 0;
        for (Map.Entry<String, Integer> entry : componentErrors.entrySet()) {
            if (entry.getValue() > maxErrors) {
                maxErrors = entry.getValue();
                mostErrorComponent = entry.getKey();
            }
        }
        System.out.println("Component with Most Errors: " + mostErrorComponent + " (" + maxErrors + " errors)");
        System.out.println();

        System.out.println("Unique Error Messages:");
        for (String msg : uniqueErrorMessages) {
            System.out.println("  - " + msg);
        }
        System.out.println();

        String busiestHour = "00";
        int maxHourEntries = 0;
        for (Map.Entry<String, Integer> entry : hourCounts.entrySet()) {
            if (entry.getValue() > maxHourEntries) {
                maxHourEntries = entry.getValue();
                busiestHour = entry.getKey();
            }
        }
        System.out.println("Busiest Hour: " + busiestHour + ":00 (" + maxHourEntries + " entries)");
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import java.util.regex.*;

public class Main {
    static class Product {
        String name;
        double price;

        Product(String name, double price) {
            this.name = name;
            this.price = price;
        }
    }

    public static void main(String[] args) {
        try {
            // 1. Make an HTTP GET request
            URL url = new URL("http://127.0.0.1:18924/api/products");
            HttpURLConnection conn = (HttpURLConnection) url.openConnection();
            conn.setRequestMethod("GET");

            BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
            StringBuilder jsonBuilder = new StringBuilder();
            String line;
            while ((line = reader.readLine()) != null) {
                jsonBuilder.append(line);
            }
            reader.close();

            String json = jsonBuilder.toString();
            List<Product> products = new ArrayList<>();

            // 2. Parse the JSON response manually
            // Regex to find each object in the array
            Pattern objectPattern = Pattern.compile("\\{[^\\}]+\\}");
            Matcher objectMatcher = objectPattern.matcher(json);

            while (objectMatcher.find()) {
                String obj = objectMatcher.group();

                // Extract name
                String name = null;
                Matcher nameMatcher = Pattern.compile("\"name\"\\s*:\\s*\"([^\"]+)\"").matcher(obj);
                if (nameMatcher.find()) {
                    name = nameMatcher.group(1);
                }

                // Extract price
                String priceStr = null;
                Matcher priceMatcher = Pattern.compile("\"price\"\\s*:\\s*([0-9]*\\.?[0-9]+)").matcher(obj);
                if (priceMatcher.find()) {
                    priceStr = priceMatcher.group(1);
                }

                if (name != null && priceStr != null) {
                    products.add(new Product(name, Double.parseDouble(priceStr)));
                }
            }

            // 3. Filter to only products where price > 50.00
            List<Product> filtered = new ArrayList<>();
            for (Product p : products) {
                if (p.price > 50.00) {
                    filtered.add(p);
                }
            }

            // 4. Sort filtered products by name ascending
            Collections.sort(filtered, new Comparator<Product>() {
                @Override
                public int compare(Product p1, Product p2) {
                    return p1.name.compareTo(p2.name);
                }
            });

            // 5. Print the output in the exact format
            System.out.println("=== Filtered Products (price > $50.00) ===");
            System.out.println();

            double total = 0;
            for (Product p : filtered) {
                System.out.printf(Locale.US, "%s: $%.2f%n", p.name, p.price);
                total += p.price;
            }

            System.out.println();
            System.out.println("Count: " + filtered.size());
            System.out.printf(Locale.US, "Total: $%.2f%n", total);

        } catch (Exception e) {
            // Fail silently or handle as needed
        }
    }
}

use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::{HashMap, BTreeSet};

fn main() {
    let path = "/tmp/…/app.log";
    let file = match File::open(path) {
        Ok(f) => f,
        Err(_) => return,
    };
    let reader = BufReader::new(file);

    let mut levels = HashMap::new();
    let mut component_errors = HashMap::new();
    let mut unique_errors = BTreeSet::new();
    let mut hour_counts = HashMap::new();

    for line_result in reader.lines() {
        let line = match line_result {
            Ok(l) => l,
            Err(_) => continue,
        };
        if line.is_empty() {
            continue;
        }

        if let Some(end_bracket) = line.find(']') {
            let timestamp = &line[1..end_bracket];
            let rest = &line[end_bracket + 2..];

            if let Some((meta, message)) = rest.split_once(" - ") {
                let meta_parts: Vec<&str> = meta.split('(').collect();
                if meta_parts.len() >= 2 {
                    let level = meta_parts[0].trim();
                    let component = meta_parts[1].trim_end_matches(')');
                    let message = message.trim();

                    *levels.entry(level.to_string()).or_insert(0) += 1;

                    if timestamp.len() >= 13 {
                        let hour = &timestamp[11..13];
                        *hour_counts.entry(hour.to_string()).or_insert(0) += 1;
                    }

                    if level == "ERROR" {
                        *component_errors.entry(component.to_string()).or_insert(0) += 1;
                        unique_errors.insert(message.to_string());
                    }
                }
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();

    println!("Entries by Level:");
    let mut sorted_levels: Vec<_> = levels.keys().collect();
    sorted_levels.sort();
    for level in sorted_levels {
        println!("  {}: {}", level, levels[level]);
    }

    println!();
    let mut max_comp = String::new();
    let mut max_comp_count = 0;
    for (comp, count) in &component_errors {
        if *count > max_comp_count {
            max_comp_count = *count;
            max_comp = comp.clone();
        } else if *count == max_comp_count && *count > 0 {
            if comp < &max_comp {
                max_comp = comp.clone();
            }
        }
    }
    println!("Component with Most Errors: {} ({} errors)", max_comp, max_comp_count);

    println!();
    println!("Unique Error Messages:");
    for msg in &unique_errors {
        println!("  - {}", msg);
    }

    println!();
    let mut max_hour = String::new();
    let mut max_hour_count = 0;
    for (hour, count) in &hour_counts {
        if *count > max_hour_count {
            max_hour_count = *count;
            max_hour = hour.clone();
        } else if *count == max_hour_count && *count > 0 {
            if hour < &max_hour {
                max_hour = hour.clone();
            }
        }
    }
    if max_hour.is_empty() {
        max_hour = "00".to_string();
    }
    println!("Busiest Hour: {}:00 ({} entries)", max_hour, max_hour_count);
}

