import * as fs from 'fs';

/**
 * The program reads a weighted undirected graph from a JSON file,
 * implements Dijkstra's algorithm to find the shortest path distance
 * from node "A" to all other nodes, and prints the results in a
 * specific format.
 */

interface Edge {
  from: string;
  to: string;
  weight: number;
}

interface GraphData {
  nodes: string[];
  edges: Edge[];
}

function main() {
  const filePath = '/tmp/…/graph.json';

  try {
    // Read and parse the graph data
    const rawData = fs.readFileSync(filePath, 'utf8');
    const data: GraphData = JSON.parse(rawData);

    const nodes = data.nodes;
    const edges = data.edges;

    // Build an adjacency list for an undirected graph
    const adj = new Map<string, Array<{ node: string; weight: number }>>();
    nodes.forEach(node => adj.set(node, []));

    edges.forEach(edge => {
      const fromNeighbors = adj.get(edge.from);
      const toNeighbors = adj.get(edge.to);
      if (fromNeighbors) fromNeighbors.push({ node: edge.to, weight: edge.weight });
      if (toNeighbors) toNeighbors.push({ node: edge.from, weight: edge.weight });
    });

    // Dijkstra's Algorithm
    const distances = new Map<string, number>();
    nodes.forEach(node => distances.set(node, Infinity));

    const startNode = "A";
    if (distances.has(startNode)) {
      distances.set(startNode, 0);
    } else {
      // If "A" is not in the nodes list, the problem context suggests it should be.
      // However, we'll handle it gracefully.
    }

    const unvisited = new Set(nodes);

    while (unvisited.size > 0) {
      let u: string | null = null;
      let minDistance = Infinity;

      // Find the unvisited node with the smallest distance
      for (const node of unvisited) {
        const dist = distances.get(node)!;
        if (dist < minDistance) {
          minDistance = dist;
          u = node;
        }
      }

      // If no reachable nodes are left, break
      if (u === null) break;

      unvisited.delete(u);

      const neighbors = adj.get(u) || [];
      for (const neighbor of neighbors) {
        const currentDist = distances.get(u)!;
        const newDist = currentDist + neighbor.weight;
        const existingDist = distances.get(neighbor.node)!;

        if (newDist < existingDist) {
          distances.set(neighbor.node, newDist);
        }
      }
    }

    // Output the results in the required format
    console.log("=== Shortest Paths from A ===");
    console.log("");

    // Sort nodes alphabetically
    const sortedNodes = [...nodes].sort();
    sortedNodes.forEach(node => {
      const dist = distances.get(node);
      // If distance is Infinity, it means the node is unreachable.
      // The prompt doesn't specify what to print for unreachable nodes,
      // so we print the value as is.
      console.log(`A -> ${node}: ${dist}`);
    });

  } catch (error) {
    // Standard error handling (silent as per requirements)
  }
}

