import Foundation

struct Edge: Codable {
    let from: String
    let to: String
    let weight: Double
}

struct GraphData: Codable {
    let nodes: [String]
    let edges: [Edge]
}

let filePath = "/tmp/…/graph.json"

func solve() {
    guard let data = try? Data(contentsOf: URL(fileURLWithPath: filePath)),
          let graphData = try? JSONDecoder().decode(GraphData.self, from: data) else {
        return
    }

    var adj = [String: [(node: String, weight: Double)]]()
    for node in graphData.nodes {
        adj[node] = []
    }

    for edge in graphData.edges {
        adj[edge.from]?.append((node: edge.to, weight: edge.weight))
        adj[edge.to]?.append((node: edge.from, weight: edge.weight))
    }

    var distances = [String: Double]()
    for node in graphData.nodes {
        distances[node] = Double.infinity
    }

    if distances["A"] != nil {
        distances["A"] = 0
    }

    var visited = Set<String>()

    while visited.count < graphData.nodes.count {
        var u: String? = nil
        var minDistance = Double.infinity

        for node in graphData.nodes {
            if !visited.contains(node) {
                let d = distances[node] ?? Double.infinity
                if d < minDistance {
                    minDistance = d
                    u = node
                }
            }
        }

        guard let current = u, minDistance != Double.infinity else {
            break
        }

        visited.insert(current)

        if let neighbors = adj[current] {
            for neighbor in neighbors {
                let currentDist = distances[current] ?? Double.infinity
                let newDist = currentDist + neighbor.weight
                if newDist < (distances[neighbor.node] ?? Double.infinity) {
                    distances[neighbor.node] = newDist
                }
            }
        }
    }

    print("=== Shortest Paths from A ===")
    print("")

    let sortedNodes = graphData.nodes.sorted()
    for node in sortedNodes {
        let d = distances[node] ?? Double.infinity
        let distStr: String
        if d == Double.infinity {
            distStr = "Infinity"
        } else if d == floor(d) {
            distStr = "\(Int(d))"
        } else {
            distStr = "\(d)"
        }
        print("A -> \(node): \(distStr)")
    }
}

