import java.io.*;
import java.nio.file.*;
import java.util.*;

public class Main {
    static class Edge {
        String to;
        int weight;
        Edge(String to, int weight) {
            this.to = to;
            this.weight = weight;
        }
    }

    static class NodeDist {
        String node;
        int dist;
        NodeDist(String node, int dist) {
            this.node = node;
            this.dist = dist;
        }
    }

    public static void main(String[] args) {
        try {
            String filePath = "/tmp/…/graph.json";
            String content = new String(Files.readAllBytes(Paths.get(filePath)));

            List<String> nodes = new ArrayList<>();
            int nodesKeyIdx = content.indexOf("\"nodes\"");
            int nodesBracketStart = content.indexOf("[", nodesKeyIdx);
            int nodesBracketEnd = content.indexOf("]", nodesBracketStart);
            String nodesPart = content.substring(nodesBracketStart + 1, nodesBracketEnd);
            String[] nodesArr = nodesPart.split(",");
            for (String s : nodesArr) {
                String n = s.replace("\"", "").trim();
                if (!n.isEmpty()) nodes.add(n);
            }

            Map<String, List<Edge>> adj = new HashMap<>();
            for (String node : nodes) {
                adj.put(node, new ArrayList<>());
            }

            int edgesKeyIdx = content.indexOf("\"edges\"");
            int edgesBracketStart = content.indexOf("[", edgesKeyIdx);
            int edgesBracketEnd = content.indexOf("]", edgesBracketStart);
            String edgesPart = content.substring(edgesBracketStart + 1, edgesBracketEnd);

            int ePos = 0;
            while ((ePos = edgesPart.indexOf("{", ePos)) != -1) {
                int eEnd = edgesPart.indexOf("}", ePos);
                String block = edgesPart.substring(ePos, eEnd + 1);

                String from = extractValue(block, "\"from\"");
                String to = extractValue(block, "\"to\"");
                String weightStr = extractValue(block, "\"weight\"");

                if (from != null && to != null && weightStr != null) {
                    int weight = Integer.parseInt(weightStr.trim());
                    if (adj.containsKey(from) && adj.containsKey(to)) {
                        adj.get(from).add(new Edge(to, weight));
                        adj.get(to).add(new Edge(from, weight));
                    }
                }
                ePos = eEnd + 1;
            }

            Map<String, Integer> distances = new HashMap<>();
            for (String node : nodes) {
                distances.put(node, Integer.MAX_VALUE);
            }

            if (distances.containsKey("A")) {
                distances.put("A", 0);
            } else {
                // If "A" is not in the nodes list, the problem implies it's not part of the graph.
                // However, the prompt implies "A" is the source.
            }

            PriorityQueue<NodeDist> pq = new PriorityQueue<>(Comparator.comparingInt(n -> n.dist));
            if (distances.containsKey("A")) {
                pq.add(new NodeDist("A", 0));
            }

            while (!pq.isEmpty()) {
                NodeDist current = pq.poll();
                String u = current.node;
                int d = current.dist;

                if (d > distances.get(u)) continue;

                List<Edge> neighbors = adj.get(u);
                if (neighbors != null) {
                    for (Edge e : neighbors) {
                        if (distances.get(u) != Integer.MAX_VALUE && distances.get(u) + e.weight < distances.get(e.to)) {
                            distances.put(e.to, distances.get(u) + e.weight);
                            pq.add(new NodeDist(e.to, distances.get(e.to)));
                        }
                    }
                }
            }

            System.out.println("=== Shortest Paths from A ===");
            System.out.println();
            Collections.sort(nodes);
            for (String node : nodes) {
                System.out.println("A -> " + node + ": " + distances.get(node));
            }

        } catch (Exception e) {
            // Silently handle errors as per standard practice for these types of tasks
        }
    }

    private static String extractValue(String block, String key) {
        int keyIdx = block.indexOf(key);
        if (keyIdx == -1) return null;
        int colonIdx = block.indexOf(":", keyIdx);
        int start = colonIdx + 1;
        while (start < block.length() && Character.isWhitespace(block.charAt(start))) {
            start++;
        }

        String val;
        if (start < block.length() && block.charAt(start) == '\"') {
            int end = block.indexOf("\"", start + 1);
            val = block.substring(start + 1, end);
            start = end + 1;
        } else {
            int end = block.indexOf(",", start);
            if (end == -1) end = block.indexOf("}", start);
            val = block.substring(start, end).trim();
        }
        return val;
    }
}

import Foundation

func isEqual(_ lhs: Any, _ rhs: Any) -> Bool {
    if let l = lhs as? String, let r = rhs as? String {
        return l == r
    }
    if let l = lhs as? NSNumber, let r = rhs as? NSNumber {
        return l.doubleValue == r.doubleValue
    }
    if let l = lhs as? Bool, let r = rhs as? Bool {
        return l == r
    }
    if let l = lhs as? [Any], let r = rhs as? [Any] {
        if l.count != r.count { return false }
        for i in 0..<l.count {
            if !isEqual(l[i], r[i]) { return false }
        }
        return true
    }
    if let l = lhs as? [String: Any], let r = rhs as? [String: Any] {
        if l.count != r.count { return false }
        for (k, v) in l {
            if let rv = r[k] {
                if !isEqual(v, rv) { return false }
            } else {
                return false
            }
        }
        return true
    }
    return false
}

func contains(_ array: [Any], _ item: Any) -> Bool {
    for element in array {
        if isEqual(element, item) { return true }
    }
    return false
}

func deepMerge(_ a: Any, _ b: Any) -> Any {
    if let dictA = a as? [String: Any], let dictB = b as? [String: Any] {
        var result = dictA
        for (key, valueB) in dictB {
            if let valueA = result[key] {
                result[key] = deepMerge(valueA, valueB)
            } else {
                result[key] = valueB
            }
        }
        return result
    } else if let arrA = a as? [Any], let arrB = b as? [Any] {
        var result = [Any]()
        let combined = arrA + arrB
        for item in combined {
            if !contains(result, item) {
                result.append(item)
            }
        }
        return result
    } else {
        return b
    }
}

func formatJSON(_ value: Any, indent: Int = 0) -> String {
    let padding = String(repeating: "  ", count: indent)
    if let dict = value as? [String: Any] {
        let sortedKeys = dict.keys.sorted()
        if sortedKeys.isEmpty { return "{}" }
        var lines = [String]()
        for key in sortedKeys {
            let val = dict[key]!
            let formattedVal = formatJSON(val, indent: indent + 1)
            lines.append("\"\(key)\": \(formattedVal)")
        }
        let joined = lines.joined(separator: ",\n")
        return "{\n" + joined.map { "\(padding)  \($0)" }.joined(separator: ",\n") + "\n" + padding + "}"
    } else if let arr = value as? [Any] {
        if arr.isEmpty { return "[]" }
        var lines = [String]()
        for item in arr {
            lines.append(formatJSON(item, indent: indent + 1))
        }
        let joined = lines.joined(separator: ",\n")
        return "[\n" + joined.map { "\(padding)  \($0)" }.joined(separator: ",\n") + "\n" + padding + "]"
    } else if let str = value as? String {
        if let data = try? JSONSerialization.data(withJSONObject: str, options: []) {
            return String(data: data, encoding: .utf8)!
        }
        return "\"\(str)\""
    } else if let num = value as? NSNumber {
        let d = num.doubleValue
        if d == floor(d) {
            return "\(Int(d))"
        } else {
            return "\(d)"
        }
    } else if let bool = value as? Bool {
        return bool ? "true" : "false"
    } else if value is NSNull {
        return "null"
    }
    return "null"
}

