            return parseValue();
        }

        private void skipWhitespace() {
            while (pos < src.length() && Character.isWhitespace(src.charAt(pos))) {
                pos++;
            }
        }

        private Object parseValue() {
            skipWhitespace();
            if (pos >= src.length()) return null;
            char c = src.charAt(pos);
            if (c == '{') return parseObject();
            if (c == '[') return parseArray();
            if (c == '"') return parseString();
            if (c == 't' || c == 'f') return parseBoolean();
            if (c == 'n') return parseNull();
            return parseNumber();
        }

        private Map<String, Object> parseObject() {
            pos++; // {
            Map<String, Object> map = new TreeMap<>();
            skipWhitespace();
            if (pos < src.length() && src.charAt(pos) == '}') {
                pos++;
                return map;
            }
            while (true) {
                skipWhitespace();
                String key = parseString();
                skipWhitespace();
                pos++; // :
                Object value = parseValue();
                map.put(key, value);
                skipWhitespace();
                if (pos < src.length() && src.charAt(pos) == '}') {
                    pos++;
                    break;
                } else {
                    pos++; // ,
                }
            }
            return map;
        }

        private List<Object> parseArray() {
            pos++; // [
            List<Object> list = new ArrayList<>();
            skipWhitespace();
            if (pos < src.length() && src.charAt(pos) == ']') {
                pos++;
                return list;
            }
            while (true) {
                list.add(parseValue());
                skipWhitespace();
                if (pos < src.length() && src.charAt(pos) == ']') {
                    pos++;
                    break;
                } else {
                    pos++; // ,
                }
            }
            return list;
        }

        private String parseString() {
            pos++; // "
            StringBuilder sb = new StringBuilder();
            while (pos < src.length()) {
                char c = src.charAt(pos);
                if (c == '"') {
                    pos++;
                    break;
                } else if (c == '\\') {
                    pos++;
                    if (pos < src.length()) {
                        char escaped = src.charAt(pos);
                        switch (escaped) {
                            case '"': sb.append('"'); break;
                            case '\\': sb.append('\\'); break;
                            case '/': sb.append('/'); break;
                            case 'b': sb.append('\b'); break;
                            case 'f': sb.append('\f'); break;
                            case 'n': sb.append('\n'); break;
                            case 'r': sb.append('\r'); break;
                            case 't': sb.append('\t'); break;
                            default: sb.append(escaped); break;
                        }
                    }
                    pos++;
                } else {
                    sb.append(c);
                    pos++;
                }
            }
            return sb.toString();
        }

        private Object parseNumber() {
            int start = pos;
            while (pos < src.length() && (Character.isDigit(src.charAt(pos)) || 
                   src.charAt(pos) == '-' || src.charAt(pos) == '.' || 
                   src.charAt(pos) == 'e' || src.charAt(pos) == 'E')) {
                pos++;
            }
            String s = src.substring(start, pos);
            if (s.contains(".") || s.contains("e") || s.contains("E")) {
                return Double.parseDouble(s);
            } else {
                try {
                    return Long.parseLong(s);
                } catch (NumberFormatException e) {
                    return Double.parseDouble(s);
                }
            }
        }

        private Object parseBoolean() {
            if (src.startsWith("true", pos)) {
                pos += 4;
                return true;
            } else {
                pos += 5;
                return false;
            }
        }

        private Object parseNull() {
            pos += 4;
            return null;
        }
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[128];
    char department[128];
    long long salary;
} Employee;

typedef struct {
    char name[128];
    long long total_salary;
    int count;
} DeptStats;

char* trim(char* str) {
    char* end;
    while (*str == ' ' || *str == '\t' || *str == '\n' || *str == '\r') str++;
    end = str + strlen(str) - 1;
    while (end > str && (*end == ' ' || *end == '\t' || *end == '\n' || *end == '\r')) {
        *end = '\0';
        end--;
    }
    return str;
}

void print_formatted_int(long long val) {
    char buf[64];
    sprintf(buf, "%lld", val);
    int len = strlen(buf);
    printf("$");
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0 && buf[i - 1] != ',') {
            printf(",");
        }
        putchar(buf[i]);
    }
}

void print_formatted_double(double val) {
    long long integer_part = (long long)val;
    int fractional_part = (int)((val - (double)integer_part) * 100 + 0.5);
    if (fractional_part >= 100) {
        integer_part++;
        fractional_part -= 100;
    }
    char buf[64];
    sprintf(buf, "%lld", integer_part);
    int len = strlen(buf);
    printf("$");
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0 && buf[i - 1] != ',') {
            printf(",");
        }
        putchar(buf[i]);
    }
    printf(".%02d", fractional_part);
}

int compare_depts(const void* a, const void* b) {
    return strcmp(((DeptStats*)a)->name, ((DeptStats*)b)->name);
}

int main(void) {
    const char* filename = "/tmp/…/employees.csv";
