        // Skip header
    }

    while (fgets(line, sizeof(line), fp)) {
        char* token;
        char* ptr = line;

        token = strtok(ptr, ",");
        if (!token) continue;

        token = strtok(NULL, ",");
        if (!token) continue;
        strcpy(employees[emp_count].name, trim(token));

        token = strtok(NULL, ",");
        if (!token) continue;
        strcpy(employees[emp_count].department, trim(token));

