        print_formatted_double((double)depts[i].total_salary / depts[i].count);
        printf("\n");
    }

    printf("\nHighest Paid: %s ($", highest_paid_emp->name);
    print_formatted_int(highest_paid_emp->salary);
    printf(")\n\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }

    printf("\nTotal Budget: $");
    print_formatted_int(total_budget);
    printf("\n");

    free(employees);
    free(depts);

    return 0;
}

