use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::BTreeMap;

struct Employee {
    name: String,
    dept: String,
    salary: f64,
}

fn format_int_currency(n: f64) -> String {
    let s = format!("{:.0}", n.round());
    let mut result = String::new();
    let chars: Vec<char> = s.chars().collect();
    let len = chars.len();
    for (i, &c) in chars.iter().enumerate() {
        result.push(c);
        let remaining = len - i - 1;
        if remaining > 0 && remaining % 3 == 0 {
            result.push(',');
        }
    }
    format!("${}", result)
}

fn format_avg_currency(n: f64) -> String {
    let s = format!("{:.2}", n);
    let parts: Vec<&str> = s.split('.').collect();
    let int_part = parts[0];
    let dec_part = if parts.len() > 1 { format!(".{}", parts[1]) } else { "".to_string() };

    let mut result = String::new();
    let chars: Vec<char> = int_part.chars().collect();
    let len = chars.len();
    for (i, &c) in chars.iter().enumerate() {
        result.push(c);
        let remaining = len - i - 1;
        if remaining > 0 && remaining % 3 == 0 {
            result.push(',');
        }
    }
    format!("${}", result + &dec_part)
}

fn main() {
    let path = "/tmp/…/employees.csv";
    let file = File::open(path).expect("Could not open file");
    let reader = BufReader::new(file);

    let mut employees = Vec::new();
    let mut lines = reader.lines();
    let _header = lines.next();

    for line in lines {
        let l = line.expect("Could not read line");
        let cols: Vec<&str> = l.split(',').map(|s| s.trim()).collect();
        if cols.len() >= 4 {
            let name = cols[1].to_string();
            let dept = cols[2].to_string();
            let salary: f64 = cols[3].parse().unwrap_or(0.0);
            employees.push(Employee { name, dept, salary });
        }
    }

    let mut averages: BTreeMap<String, (f64, usize)> = BTreeMap::new();
    let mut dept_counts: BTreeMap<String, usize> = BTreeMap::new();
    let mut highest_paid_name = String::new();
    let mut highest_paid_salary = -1.0;
    let mut total_budget = 0.0;

    for emp in &employees {
        let entry = averages.entry(emp.dept.clone()).or_insert((0.0, 0));
        entry.0 += emp.salary;
        entry.1 += 1;

        let count_entry = dept_counts.entry(emp.dept.clone()).or_insert(0);
        *count_entry += 1;

        total_budget += emp.salary;

        if emp.salary > highest_paid_salary {
            highest_paid_salary = emp.salary;
            highest_paid_name = emp.name.clone();
        }
    }

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for (dept, (total_sal, count)) in &averages {
        let avg = total_sal / (*count as f64);
        println!("  {}: {}", dept, format_avg_currency(*avg));
    }
    println!();
    println!("Highest Paid: {} ({})", highest_paid_name, format_int_currency(highest_paid_salary));
    println!();
    println!("Departments with >2 employees:");
    for (dept, &count) in &dept_counts {
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: {}", format_int_currency(total_budget));
}

