import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        String baseDirPath = "/tmp/…/project_tree";
        Path baseDir = Paths.get(baseDirPath);

        TreeMap<String, List<FileStats>> groups = new TreeMap<>();

        try {
            Files.walkFileTree(baseDir, new SimpleFileVisitor<Path>() {
                @Override
                public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                    String name = file.getFileName().toString();
                    int lastDot = name.lastIndexOf('.');
                    String ext = (lastDot == -1) ? "" : name.substring(lastDot);

                    long lines = 0;
                    long chars = attrs.size();

                    try (InputStream is = Files.newInputStream(file)) {
                        byte[] buffer = new byte[8192];
                        int bytesRead;
                        while ((bytesRead = is.read(buffer)) != -1) {
                            for (int i = 0; i < bytesRead; i++) {
                                if (buffer[i] == '\n') {
                                    lines++;
                                }
                            }
                        }
                    } catch (IOException e) {
                        // Skip files that cannot be read
                    }

                    Path relative = baseDir.relativize(file.toAbsolutePath());
                    String relPath = relative.toString().replace('\\', '/');

                    FileStats stats = new FileStats(relPath, lines, chars);
                    groups.computeIfAbsent(ext, k -> new ArrayList<>()).add(stats);

                    return FileVisitResult.CONTINUE;
                }
            });
        } catch (IOException e) {
            // Handle directory access errors
        }

        System.out.println("=== File Tree Analysis ===");
        System.out.println();

        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<FileStats>> entry : groups.entrySet()) {
            List<FileStats> list = entry.getValue();
            Collections.sort(list, Comparator.comparing(s -> s.relativePath));

            long extLines = 0;
            long extChars = 0;

            System.out.println("Extension: " + entry.getKey());
            System.out.println("  Files: " + list.size());

            for (FileStats fs : list) {
                extLines += fs.lines;
                extChars += fs.chars;
            }

            System.out.println("  Total Lines: " + extLines);
            System.out.println("  Total Characters: " + extChars);

            for (FileStats fs : list) {
                System.out.println("    " + fs.relativePath + ": " + fs.lines + " lines, " + fs.chars + " chars");
            }

            totalFiles += list.size();
            totalLines += extLines;
            totalChars += extChars;
        }

        System.out.println();
        System.out.println("Total: " + totalFiles + " files, " + totalLines + " lines, " + totalChars + " characters");
    }

    static class FileStats {
        String relativePath;
        long lines;
        long chars;

        FileStats(String relativePath, long lines, long chars) {
            this.relativePath = relativePath;
            this.lines = lines;
            this.chars = chars;
        }
    }
}

use std::io::{Read, Write};
use std::net::TcpStream;

struct Product {
    name: String,
    price: f64,
}

fn main() {
    // 1. Establish a TCP connection to the specified host and port
    let mut stream = TcpStream::connect("127.0.0.1:18924").expect("Failed to connect to server");

    // 2. Send the HTTP GET request
    let request = "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18924\r\nConnection: close\r\n\r\n";
    stream.write_all(request.as_bytes()).expect("Failed to write request");

    // 3. Read the entire response into a string
    let mut response = String::new();
    stream.read_to_string(&mut response).expect("Failed to read response");

    // 4. Extract the body by finding the double CRLF that separates headers from the body
    let body = response.split("\r\n\r\n").nth(1).unwrap_or("").trim();

    // 5. Manually parse the JSON array of objects without external dependencies
    let mut products = Vec::new();
    let mut current_pos = 0;

    while let Some(start_idx) = body[current_pos..].find('{') {
        let actual_start = current_pos + start_idx;
        if let Some(end_idx) = body[actual_start..].find('}') {
            let actual_end = actual_start + end_idx;
            let obj = &body[actual_start..actual_end + 1];

            // Extract "name"
            let mut name = String::new();
            if let Some(n_idx) = obj.find("\"name\":") {
                let mut n_search = n_idx + 8;
                while n_search < obj.len() && obj.as_bytes()[n_search] != b'"' {
                    n_search += 1;
                }
                let n_start = n_search + 1;
                if let Some(n_end) = obj[n_start..].find('"') {
                    name = obj[n_start..n_start + n_end].to_string();
                }
            }

            // Extract "price"
            let mut price = 0.0;
            if let Some(p_idx) = obj.find("\"price\":") {
                let mut p_search = p_idx + 8;
                while p_search < obj.len() && !obj.as_bytes()[p_search].is_ascii_digit() && obj.as_bytes()[p_search] != b'.' {
                    p_search += 1;
                }
                let p_end = obj[p_search..].find(|c: char| !c.is_digit(10) && c != '.').unwrap_or(obj[p_search..].len());
                let price_str = &obj[p_search..p_search + p_end];
                if let Ok(p) = price_str.parse::<f64>() {
                    price = p;
                }
            }

            // 6. Filter products where price > 50.00
            if price > 50.00 {
                products.push(Product { name, price });
            }

            current_pos = actual_end + 1;
        } else {
            break;
        }
    }

    // 7. Sort filtered products by name ascending (alphabetical)
    products.sort_by(|a, b| a.name.cmp(&b.name));

    // 8. Print the output in the exact specified format
    println!("=== Filtered Products (price > $50.00) ===");
    println!();

    let mut total_price = 0.0;
    for p in &products {
        println!("{}: ${:.2}", p.name, p.price);
        total_price += p.price;
    }

    println!();
    println!("Count: {}", products.len());
    println!("Total: ${:.2}", total_price);
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) {
        String hostname = execute("hostname");
        String os = execute("uname", "-s");
        String architecture = execute("uname", "-m");
        String username = execute("whoami");

        System.out.println("{");
        System.out.println("  \"hostname\": \"" + hostname + "\",");
        System.out.println("  \"os\": \"" + os + "\",");
        System.out.println("  \"architecture\": \"" + architecture + "\",");
        System.out.println("  \"username\": \"" + username + "\"");
        System.out.println("}");
    }

    private static String execute(String... command) {
        try {
            ProcessBuilder pb = new ProcessBuilder(command);
            Process process = pb.start();
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String output = reader.readLine();
            process.waitFor();
            return (output != null) ? output.trim() : "";
        } catch (Exception e) {
            return "";
        }
    }
}

