    for (int i = 0; i < err_msgs_count; i++) {
        printf("  - %s\n", err_msgs[i].msg);
    }
    printf("\n");

    int max_h_count = -1;
    int busiest_h = 0;
    for (int i = 0; i < 24; i++) {
        if (hour_counts[i] > max_h_count) {
