            busiest_h = i;
        }
    }
    printf("Busiest Hour: %02d:00 (%d entries)\n", busiest_h, max_h_count);

    for (int i = 0; i < levels_count; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < comps_count; i++) free(comps[i].name);
    free(comps);
    for (int i = 0; i < err_msgs_count; i++) free(err_msgs[i].msg);
    free(err_msgs);

    return 0;
}

