#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

/**
 * Executes a system command and captures its output into a dynamically allocated string.
 * Trailing newlines and whitespace are stripped.
 */
char* get_command_output(const char* cmd) {
    FILE* fp = popen(cmd, "r");
    if (fp == NULL) {
        return NULL;
    }

    // Allocate a buffer large enough for typical system command outputs
    char* buffer = (char*)malloc(2048);
    if (buffer == NULL) {
        pclose(fp);
        return NULL;
    }

    if (fgets(buffer, 2048, fp) == NULL) {
        buffer[0] = '\0';
    } else {
        size_t len = strlen(buffer);
        // Strip trailing newlines and whitespace
        while (len > 0 && isspace((unsigned char)buffer[len - 1])) {
            buffer[--len] = '\0';
        }
    }

    pclose(fp);
    return buffer;
}

int main(void) {
    // Capture the required information
    char* hostname = get_command_output("hostname");
    char* os = get_command_output("uname -s");
    char* architecture = get_command_output("uname -m");
    char* username = get_command_output("whoami");

    // Fallback to "unknown" if a command fails
    hostname = hostname ? hostname : "unknown";
    os = os ? os : "unknown";
    architecture = architecture ? architecture : "unknown";
    username = username ? username : "unknown";

    // Output the JSON object with the exact keys and order specified
    printf("{\n");
    printf("  \"hostname\": \"%s\",\n", hostname);
    printf("  \"os\": \"%s\",\n", os);
    printf("  \"architecture\": \"%s\",\n", architecture);
    printf("  \"username\": \"%s\"\n", username);
    printf("}\n");

    // Clean up allocated memory
    free(hostname);
    free(os);
    free(architecture);
    free(username);

    return 0;
}

use std::process::Command;

fn get_command_output(cmd: &str, args: &[&str]) -> String {
    let output = Command::new(cmd)
        .args(args)
        .output()
        .expect("Failed to execute command");

    String::from_utf8(output.stdout)
        .expect("Failed to convert output to UTF-8")
        .trim()
        .to_string()
}

