#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h>

typedef struct {
    char name[256];
    double price;
} Product;

int compare_products(const void *a, const void *b) {
    const Product *p1 = (const Product *)a;
    const Product *p2 = (const Product *)b;
    return strcmp(p1->name, p2->name);
}

int main(void) {
    int sock;
    struct sockaddr_in server;
    char *buffer = malloc(1048576); // 1MB buffer for response
    if (!buffer) return 1;

    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        free(buffer);
        return 1;
    }

    server.sin_family = AF_INET;
    server.sin_port = htons(18924);
    if (inet_pton(AF_INET, "127.0.0.1", &server.sin_addr) <= 0) {
        close(sock);
        free(buffer);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&server, sizeof(server)) < 0) {
        close(sock);
        free(buffer);
        return 1;
    }

    const char *request = "GET /api/products HTTP/1.1\r\n"
                           "Host: 127.0.0.1:18924\r\n"
                           "Connection: close\r\n\r\n";
    send(sock, request, strlen(request), 0);

    int total_received = 0;
    int bytes_received;
    while ((bytes_received = recv(sock, buffer + total_received, 1048576 - total_received - 1, 0)) > 0) {
        total_received += bytes_received;
        buffer[total_received] = '\0';
    }
    close(sock);

    char *json_body = strstr(buffer, "\r\n\r\n");
    if (!json_body) {
        free(buffer);
        return 1;
    }
    json_body += 4;

    Product *all_products = malloc(10000 * sizeof(Product));
    int count_all = 0;

    char *obj_ptr = json_body;
    while ((obj_ptr = strchr(obj_ptr, '{')) != NULL) {
        char *obj_end = strchr(obj_ptr, '}');
        if (!obj_end) break;

        char *name_key = strstr(obj_ptr, "\"name\"");
        if (name_key && name_key < obj_end) {
            char *v_start = strchr(name_key + 6, ':');
            if (v_start) {
                v_start = strchr(v_start, '"');
                if (v_start) {
                    v_start++;
                    char *v_end = strchr(v_start, '"');
                    if (v_end) {
                        int len = (int)(v_end - v_start);
                        if (len > 255) len = 255;
                        memcpy(all_products[count_all].name, v_start, len);
                        all_products[count_all].name[len] = '\0';
                    }
                }
            }
        }

        char *price_key = strstr(obj_ptr, "\"price\"");
        if (price_key && price_key < obj_end) {
            char *v_start = strchr(price_key + 7, ':');
            if (v_start) {
                while (*v_start == ' ' || *v_start == '\t' || *v_start == '\n' || *v_start == '\r') {
                    v_start++;
                }
                all_products[count_all].price = strtod(v_start, NULL);
            }
        }
        count_all++;
        obj_ptr = obj_end;
    }

    Product *filtered = malloc(count_all * sizeof(Product));
    int count_filtered = 0;
    for (int i = 0; i < count_all; i++) {
        if (all_products[i].price > 50.00) {
            filtered[count_filtered++] = all_products[i];
        }
    }

    qsort(filtered, count_filtered, sizeof(Product), compare_products);

    double total_price = 0;
    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < count_filtered; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
        total_price += filtered[i].price;
    }
    printf("\n");
    printf("Count: %d\n", count_filtered);
    printf("Total: $%.2f\n", total_price);

    free(all_products);
    free(filtered);
    free(buffer);

    return 0;
}

