    }
    int count_all = 0;

    char *obj_ptr = json_body;
    while ((obj_ptr = strchr(obj_ptr, '{')) != NULL && count_all < 10000) {
        char *obj_end = strchr(obj_ptr, '}');
        if (!obj_end) break;

        char *name_key = strstr(obj_ptr, "\"name\"");
        if (name_key && name_key < obj_end) {
            char *colon = strchr(name_key, ':');
            if (colon && colon < obj_end) {
                char *v_start = strchr(colon + 1, '"');
                if (v_start && v_start < obj_end) {
                    v_start++;
                    char *v_end = strchr(v_start, '"');
                    if (v_end && v_end < obj_end) {
                        int len = (int)(v_end - v_start);
                        if (len > 255) len = 255;
                        memcpy(all_products[count_all].name, v_start, len);
                        all_products[count_all].name[len] = '\0';
                    }
                }
            }
        }

        char *price_key = strstr(obj_ptr, "\"price\"");
        if (price_key && price_key < obj_end) {
            char *colon = strchr(price_key, ':');
            if (colon && colon < obj_end) {
                char *v_start = colon + 1;
                while (*v_start == ' ' || *v_start == '\t' || *v_start == '\n' || *v_start == '\r') {
                    v_start++;
                }
                all_products[count_all].price = strtod(v_start, NULL);
            }
        }
        count_all++;
        obj_ptr = obj_end;
    }

    Product *filtered = malloc(count_all * sizeof(Product));
    int count_filtered = 0;
    for (int i = 0; i < count_all; i++) {
        if (all_products[i].price > 50.00) {
            filtered[count_filtered++] = all_products[i];
        }
    }

    qsort(filtered, count_filtered, sizeof(Product), compare_products);

    double total_price = 0;
    printf("=== Filtered Products (price > $50.00) ===\n\n");
    for (int i = 0; i < count_filtered; i++) {
        printf("%s: $%.2f\n", filtered[i].name, filtered[i].price);
        total_price += filtered[i].price;
    }
    printf("\n");
    printf("Count: %d\n", count_filtered);
    printf("Total: $%.2f\n", total_price);

    free(all_products);
    free(filtered);
    free(buffer);

    return 0;
}

use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Value {
    Object(BTreeMap<String, Value>),
    Array(Vec<Value>),
    String(String),
    Number(f64),
    Bool(bool),
    Null,
}

struct Parser<'a> {
    input: &'a str,
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(input: &'a str) -> Self {
        Parser {
            input,
            pos: 0,
        }
    }

    fn skip_whitespace(&mut self) {
        while self.pos < self.input.len() && self.input[self.pos].is_whitespace() {
            self.pos += 1;
        }
    }

    fn parse_value(&mut self) -> Value {
        self.skip_whitespace();
        if self.pos >= self.input.len() {
            panic!("Unexpected EOF");
        }
        let first = self.input[self.pos..].chars().next().unwrap();
        match first {
            '{' => self.parse_object(),
            '[' => self.parse_array(),
            '"' => self.parse_string(),
            't' => {
                self.parse_bool("true");
                Value::Bool(true)
            }
            'f' => {
                self.parse_bool("false");
                Value::Bool(false)
            }
            'n' => {
                self.parse_null();
                Value::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_object(&mut self) -> Value {
        self.pos += 1; // skip {
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != '}' {
            let key = self.parse_string();
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ':' {
                self.pos += 1;
            }
            self.skip_whitespace();
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // skip }
        Value::Object(map)
    }

    fn parse_array(&mut self) -> Value {
        self.pos += 1; // skip [
        let mut arr = Vec::new();
        self.skip_whitespace();
        while self.pos < self.input.len() && self.input[self.pos] != ']' {
            arr.push(self.parse_value());
            self.skip_whitespace();
            if self.pos < self.input.len() && self.input[self.pos] == ',' {
                self.pos += 1;
                self.skip_whitespace();
            }
        }
        self.pos += 1; // skip ]
        Value::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1; // skip "
        let mut s = String::new();
        while self.pos < self.input.len() && self.input[self.pos] != '"' {
            if self.input[self.pos] == '\\' {
                self.pos += 1;
                if self.pos < self.input.len() {
                    match self.input.as_bytes()[self.pos] {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'b' => s.push('\x08'),
                        b'f' => s.push('\x0c'),
                        b'n' => s.push('\n'),
                        b'r' => s.push('\r'),
                        b't' => s.push('\t'),
                        _ => s.push(self.input.as_bytes()[self.pos] as char),
                    }
                }
            } else {
                s.push(self.input.as_bytes()[self.pos] as char);
            }
            self.pos += 1;
        }
        self.pos += 1; // skip "
        s
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        while self.pos < self.input.len() {
            let c = self.input.as_bytes()[self.pos] as char;
            if c.is_ascii_digit() || c == '.' || c == '-' || c == 'e' || c == 'E' || c == '+' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = &self.input[start..self.pos];
        Value::Number(s.parse::<f64>().unwrap_or(0.0))
    }

    fn parse_bool(&mut self, expected: &str) {
        let len = expected.len();
        if self.pos + len <= self.input.len() && &self.input[self.pos..self.pos + len] == expected {
            self.pos += len;
        } else {
            panic!("Expected {}", expected);
        }
    }

    fn parse_null(&mut self) {
        let len = "null".len();
        if self.pos + len <= self.input.len() && &self.input[self.pos..self.pos + len] == "null" {
            self.pos += len;
        } else {
            panic!("Expected null");
        }
    }
}

fn merge(a: Value, b: Value) -> Value {
    match (a, b) {
        (Value::Object(mut map_a), Value::Object(map_b)) => {
            for (k, v_b) in map_b {
                if let Some(v_a) = map_a.get(&k) {
                    map_a.insert(k, merge(v_a.clone(), v_b));
                } else {
                    map_a.insert(k, v_b);
                }
            }
            Value::Object(map_a)
        }
        (Value::Array(vec_a), Value::Array(vec_b)) => {
            let mut result = vec_a;
            for item_b in vec_b {
                if !result.contains(&item_b) {
                    result.push(item_b);
                }
            }
            Value::Array(result)
        }
        (_, b) => b,
    }
}

fn to_json(val: &Value, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    match val {
        Value::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let mut res = String::from("{\n");
            let mut keys: Vec<_> = map.keys().collect();
            for i in 0..keys.len() {
                let k = keys[i];
                let v = &map[k];
                res.push_str(&format!("{}  \"{}\": {}", pad, k, to_json(v, indent + 1)));
                if i < keys.len() - 1 {
                    res.push(',');
                }
                res.push('\n');
            }
            res.push_str(&pad);
            res.push('}');
            res
        }
        Value::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut res = String::from("[\n");
            for i in 0..arr.len() {
                let v = &arr[i];
                res.push_str(&format!("{}  {}", pad, to_json(v, indent + 1)));
                if i < arr.len() - 1 {
                    res.push(',');
                }
                res.push('\n');
            }
            res.push_str(&pad);
            res.push(']');
            res
        }
        Value::String(s) => {
            let mut escaped = String::new();
            for c in s.chars() {
                match c {
                    '"' => escaped.push_str("\\\""),
                    '\\' => escaped.push_str("\\\\"),
                    '\n' => escaped.push_str("\\n"),
                    '\r' => escaped.push_str("\\r"),
                    '\t' => escaped.push_str("\\t"),
                    _ => escaped.push(c),
                }
            }
            format!("\"{}\"", escaped)
        }
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "null".to_string(),
    }
}

fn main() {
    let path_a = "/tmp/…/config_a.json";
    let path_b = "/tmp/…/config_b.json";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let mut parser_a = Parser::new(&content_a);
    let val_a = parser_a.parse_value();

    let mut parser_b = Parser::new(&content_b);
    let val_b = parser_b.parse_value();

    let merged = merge(val_a, val_b);
    println!("{}", to_json(&merged, 0));
}

