/**
 * Matrix Multiplication and Determinant Calculation
 * 
 * This program performs matrix multiplication (A x B) and computes 
 * the determinant of the resulting matrix C.
 */

const A: number[][] = [
  [1, 2, 3],
  [4, 5, 6],
  [7, 8, 9]
];

const B: number[][] = [
  [9, 8, 7],
  [6, 5, 4],
  [3, 2, 1]
];

/**
 * Multiplies two matrices A and B.
 * @param matA The first matrix.
 * @param matB The second matrix.
 * @returns The resulting matrix C = A x B.
 */
function multiplyMatrices(matA: number[][], matB: number[][]): number[][] {
  const rowsA = matA.length;
  const colsA = matA[0].length;
  const colsB = matB[0].length;
  const result: number[][] = Array.from({ length: rowsA }, () => new Array(colsB).fill(0));

  for (let i = 0; i < rowsA; i++) {
    for (let j = 0; j < colsB; j++) {
      for (let k = 0; k < colsA; k++) {
        result[i][j] += matA[i][k] * matB[k][j];
      }
    }
  }
  return result;
}

/**
 * Computes the determinant of a square matrix recursively.
 * @param matrix The matrix to compute the determinant of.
 * @returns The determinant.
 */
function computeDeterminant(matrix: number[][]): number {
  const n = matrix.length;
  if (n === 1) return matrix[0][0];
  if (n === 2) return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0];

  let det = 0;
  for (let i = 0; i < n; i++) {
    const subMatrix = matrix.slice(1).map(row => row.filter((_, j) => j !== i));
    det += Math.pow(-1, i) * matrix[0][i] * computeDeterminant(subMatrix);
  }
  return det;
}

/**
 * Formats a matrix for output as specified.
 * Each row has a 2-space indent, and each value is right-justified in a 4-character field.
 * Fields are separated by a single space.
 * @param matrix The matrix to format.
 * @returns The formatted string.
 */
function formatMatrix(matrix: number[][]): string {
  return matrix.map(row => {
    const formattedRow = row.map(v => v.toString().padStart(4, ' ')).join(' ');
    return `  ${formattedRow}`;
  }).join('\n');
}

function main(): void {
  const C = multiplyMatrices(A, B);
  const detC = computeDeterminant(C);

  process.stdout.write("=== Matrix Operations ===\n\n");

  process.stdout.write("Matrix A:\n");
  process.stdout.write(formatMatrix(A) + "\n\n");

  process.stdout.write("Matrix B:\n");
  process.stdout.write(formatMatrix(B) + "\n\n");

  process.stdout.write("A x B =\n");
  process.stdout.write(formatMatrix(C) + "\n\n");

  process.stdout.write(`Determinant: ${detC}\n`);
}

main();

