fn multiply(a: &Vec<Vec<i32>>, b: &Vec<Vec<i32>>) -> Vec<Vec<i32>> {
    let rows_a = a.len();
    let cols_a = a[0].len();
    let cols_b = b[0].len();
    let mut c = vec![vec![0; cols_b]; rows_a];
    for i in 0..rows_a {
        for j in 0..cols_b {
            for k in 0..cols_a {
                c[i][j] += a[i][k] * b[k][j];
            }
        }
    }
    c
}

fn determinant(m: &Vec<Vec<i32>>) -> i32 {
    let n = m.len();
    if n == 1 {
        return m[0][0];
    }
    if n == 2 {
        return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    }
    let mut det = 0;
    for i in 0..n {
        let mut submatrix = vec![vec![0; n - 1]; n - 1];
        for row in 1..n {
            let mut col_idx = 0;
            for col in 0..n {
                if col == i {
                    continue;
                }
                submatrix[row - 1][col_idx] = m[row][col];
                col_idx += 1;
            }
        }
        let sign = if i % 2 == 0 { 1 } else { -1 };
        det += sign * m[0][i] * determinant(&submatrix);
    }
    det
}

fn print_matrix(matrix: &Vec<Vec<i32>>) {
    for row in matrix {
        print!("  ");
        for (i, &val) in row.iter().enumerate() {
            print!("{:4}", val);
            if i < row.len() - 1 {
                print!(" ");
            }
        }
        println!();
    }
}

