        vec![4, 5, 6],
        vec![7, 8, 9],
    ];
    let b = vec![
        vec![9, 8, 7],
        vec![6, 5, 4],
        vec![3, 2, 1],
    ];

    let c = multiply(&a, &b);
    let det_c = determinant(&c);

