    println!("Determinant: {}", det_c);
}

use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn walk_dir(current_path: &Path, base_path: &Path, stats_map: &mut BTreeMap<String, Vec<(String, u64, u64)>>) {
    if let Ok(entries) = fs::read_dir(current_path) {
        for entry in entries.flatten() {
            let path = entry.path();
            if let Ok(metadata) = fs::symlink_metadata(&path) {
                if metadata.is_dir() {
                    walk_dir(&path, base_path, stats_map);
                } else if metadata.is_file() {
                    if let Ok(content) = fs::read(&path) {
                        let lines = content.iter().filter(|&&b| b == b'\n').count() as u64;
                        let chars = content.len() as u64;

                        let rel_path = path.strip_prefix(base_path)
                            .map(|p| p.to_string_lossy().replace('\\', "/").into_owned())
                            .unwrap_or_else(|| path.to_string_lossy().replace('\\', "/").into_owned());

                        let ext = path.extension()
                            .and_then(|s| s.to_str())
                            .map(|s| format!(".{}", s))
                            .unwrap_or_else(|| ".".to_string());

                        stats_map.entry(ext).or_insert_with(Vec::new).push((rel_path, lines, chars));
                    }
                }
            }
        }
    }
}

fn main() {
    let base_path = Path::new("/tmp/…/project_tree");
    let mut stats_map: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    walk_dir(base_path, base_path, &mut stats_map);

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0u64;
    let mut total_lines = 0u64;
    let mut total_chars = 0u64;

    for (ext, files) in &stats_map {
        let mut sorted_files = files.clone();
        sorted_files.sort_by(|a, b| a.0.cmp(&b.0));

        let mut ext_lines = 0u64;
        let mut ext_chars = 0u64;
        for &(_, lines, chars) in &sorted_files {
            ext_lines += lines;
            ext_chars += chars;
        }

        println!("Extension: {}", ext);
        println!("  Files: {}", sorted_files.len());
        println!("  Total Lines: {}", ext_lines);
        println!("  Total Characters: {}", ext_chars);
        for (path, lines, chars) in sorted_files {
            println!("    {}: {} lines, {} chars", path, lines, chars);
        }

        total_files += sorted_files.len() as u64;
        total_lines += ext_lines;
        total_chars += ext_chars;
    }

    println!();
    println!("Total: {} files, {} lines, {} characters", total_files, total_lines, total_chars);
}

