typedef struct Edge {
    int to;
    double weight;
    struct Edge *next;
} Edge;

typedef struct {
    int node_id;
    double dist;
} HeapNode;

typedef struct {
    HeapNode *data;
    int size;
    int capacity;
} MinHeap;

MinHeap* create_heap(int capacity) {
    MinHeap *heap = (MinHeap*)malloc(sizeof(MinHeap));
    heap->data = (HeapNode*)malloc(capacity * sizeof(HeapNode));
    heap->size = 0;
    heap->capacity = capacity;
    return heap;
}

void push(MinHeap *heap, int node_id, double dist) {
    if (heap->size == heap->capacity) {
        heap->capacity *= 2;
        heap->data = (HeapNode*)realloc(heap->data, heap->capacity * sizeof(HeapNode));
    }
    int i = heap->size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap->data[p].dist <= dist) break;
        heap->data[i] = heap->data[p];
        i = p;
    }
    heap->data[i].node_id = node_id;
    heap->data[i].dist = dist;
}

HeapNode pop(MinHeap *heap) {
    HeapNode res = heap->data[0];
    heap->data[0] = heap->data[--heap->size];
    int i = 0;
    while (i * 2 + 1 < heap->size) {
        int child = i * 2 + 1;
        if (child + 1 < heap->size && heap->data[child + 1].dist < heap->data[child].dist) {
            child++;
        }
        if (heap->data[i].dist <= heap->data[child].dist) break;
        HeapNode tmp = heap->data[i];
        heap->data[i] = heap->data[child];
        heap->data[child] = tmp;
        i = child;
    }
    return res;
}

int is_empty(MinHeap *heap) {
    return heap->size == 0;
}

void free_heap(MinHeap *heap) {
    free(heap->data);
    free(heap);
}

