#define HASH_SIZE 100003
typedef struct HashEntry {
    char *name;
    int id;
    struct HashEntry *next;
} HashEntry;

HashEntry **hash_table;

void init_hash_table() {
    hash_table = (HashEntry**)calloc(HASH_SIZE, sizeof(HashEntry*));
}

void insert_hash_table(const char *name, int id) {
    unsigned int h = 0;
    for (int i = 0; name[i] != '\0'; i++) h = h * 31 + name[i];
    h %= HASH_SIZE;
    HashEntry *entry = (HashEntry*)malloc(sizeof(HashEntry));
    entry->name = (char*)malloc(strlen(name) + 1);
    strcpy(entry->name, name);
    entry->id = id;
    entry->next = hash_table[h];
    hash_table[h] = entry;
}

int get_id(const char *name) {
    unsigned int h = 0;
    for (int i = 0; name[i] != '\0'; i++) h = h * 31 + name[i];
    h %= HASH_SIZE;
    HashEntry *entry = hash_table[h];
    while (entry) {
        if (strcmp(entry->name, name) == 0) return entry->id;
        entry = entry->next;
    }
    return -1;
}

void free_hash_table() {
    for (int i = 0; i < HASH_SIZE; i++) {
        HashEntry *entry = hash_table[i];
        while (entry) {
            HashEntry *tmp = entry;
            entry = entry->next;
            free(tmp->name);
            free(tmp);
        }
    }
    free(hash_table);
}

