    for (int i = 0; i < num_nodes; i++) free(node_names[i]);
    free(node_names);
    free_hash_table();
    free(json);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>

typedef struct FileEntry {
    char *rel_path;
    char *ext;
    long long lines;
    long long chars;
} FileEntry;

typedef struct ExtGroup {
    char *ext;
    FileEntry **entries;
    int count;
    long long total_lines;
    long long total_chars;
} ExtGroup;

FileEntry **all_files = NULL;
int all_files_count = 0;
int all_files_capacity = 0;

char *my_strdup(const char *s) {
    size_t len = strlen(s) + 1;
    char *d = malloc(len);
    if (d) memcpy(d, s, len);
    return d;
}

void add_file(const char *rel_path, const char *ext, long long lines, long long chars) {
    if (all_files_count >= all_files_capacity) {
        all_files_capacity = (all_files_capacity == 0) ? 1024 : all_files_capacity * 2;
        all_files = realloc(all_files, sizeof(FileEntry *) * all_files_capacity);
    }
    FileEntry *fe = malloc(sizeof(FileEntry));
    fe->rel_path = my_strdup(rel_path);
    fe->ext = my_strdup(ext);
    fe->lines = lines;
    fe->chars = chars;
    all_files[all_files_count++] = fe;
}

void walk(const char *base_path, const char *current_path) {
    DIR *dir = opendir(current_path);
    if (!dir) return;

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char full_path[4096];
        snprintf(full_path, sizeof(full_path), "%s/%s", current_path, entry->d_name);

        struct stat st;
        if (lstat(full_path, &st) == 0) {
            if (S_ISDIR(st.st_mode)) {
                walk(base_path, full_path);
            } else if (S_ISREG(st.st_mode)) {
                long long lines = 0;
                long long chars = 0;
                FILE *f = fopen(full_path, "rb");
                if (f) {
                    char buf[8192];
                    size_t bytes_read;
                    while ((bytes_read = fread(buf, 1, sizeof(buf), f)) > 0) {
                        chars += bytes_read;
                        for (size_t i = 0; i < bytes_read; i++) {
                            if (buf[i] == '\n') lines++;
                        }
                    }
                    fclose(f);
                }

                const char *rel = full_path + strlen(base_path);
                if (*rel == '/') rel++;

                const char *dot = strrchr(entry->d_name, '.');
                const char *ext = "";
                if (dot && dot != entry->d_name) {
                    ext = dot;
                }

                add_file(rel, ext, lines, chars);
            }
        }
    }
    closedir(dir);
}

int compare_groups(const void *a, const void *b) {
    const ExtGroup *ga = (const ExtGroup *)a;
    const ExtGroup *gb = (const ExtGroup *)b;
    return strcmp(ga->ext, gb->ext);
}

int compare_files(const void *a, const void *b) {
    const FileEntry *fa = (const FileEntry *)a;
    const FileEntry *fb = (const FileEntry *)b;
    return strcmp(fa->rel_path, fb->rel_path);
}

int main(void) {
    const char *base_path = "/tmp/…/project_tree";
    walk(base_path, base_path);

    ExtGroup *groups = NULL;
    int group_count = 0;
    int group_capacity = 0;

    for (int i = 0; i < all_files_count; i++) {
        FileEntry *fe = all_files[i];
        int found_idx = -1;
        for (int j = 0; j < group_count; j++) {
            if (strcmp(groups[j].ext, fe->ext) == 0) {
                found_idx = j;
                break;
            }
        }
        if (found_idx == -1) {
            if (group_count >= group_capacity) {
                group_capacity = (group_capacity == 0) ? 1024 : group_capacity * 2;
                groups = realloc(groups, sizeof(ExtGroup) * group_capacity);
            }
            groups[group_count].ext = my_strdup(fe->ext);
            groups[group_count].entries = NULL;
            groups[group_count].count = 0;
            groups[group_count].total_lines = 0;
            groups[group_count].total_chars = 0;
            found_idx = group_count;
            group_count++;
        }
        ExtGroup *found = &groups[found_idx];
        found->entries = realloc(found->entries, sizeof(FileEntry *) * (found->count + 1));
        found->entries[found->count] = fe;
        found->count++;
        found->total_lines += fe->lines;
        found->total_chars += fe->chars;
    }

    qsort(groups, group_count, sizeof(ExtGroup), compare_groups);

    for (int i = 0; i < group_count; i++) {
        qsort(groups[i].entries, groups[i].count, sizeof(FileEntry *), compare_files);
    }

    printf("=== File Tree Analysis ===\n\n");
    long long total_files_count = 0;
    long long total_lines_all = 0;
    long long total_chars_all = 0;

    for (int i = 0; i < group_count; i++) {
        printf("Extension: %s\n", groups[i].ext);
        printf("  Files: %d\n", groups[i].count);
        printf("  Total Lines: %lld\n", groups[i].total_lines);
        printf("  Total Characters: %lld\n", groups[i].total_chars);
        for (int j = 0; j < groups[i].count; j++) {
            printf("    %s: %lld lines, %lld chars\n", 
                   groups[i].entries[j]->rel_path, 
                   groups[i].entries[j]->lines, 
                   groups[i].entries[j]->chars);
        }
        total_files_count += groups[i].count;
        total_lines_all += groups[i].total_lines;
        total_chars_all += groups[i].total_chars;
    }

    printf("\nTotal: %lld files, %lld lines, %lld characters\n", 
           total_files_count, total_lines_all, total_chars_all);

    return 0;
}

